package com.game_manager.gm.report;
import com.game_manager.gm.common.security.*; import com.game_manager.gm.jobs.JobService; import com.game_manager.gm.user.UserRepository; import java.time.*; import java.util.Map; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @ConditionalOnProperty(prefix="app.jobs",name="enabled",havingValue="true")
public class ReportScheduleWorker {private final ReportScheduleRepository schedules;private final ReportRequestRepository requests;private final UserRepository users;private final JobService jobs;private final Clock clock;
 public ReportScheduleWorker(ReportScheduleRepository s,ReportRequestRepository r,UserRepository u,JobService j,Clock c){schedules=s;requests=r;users=u;jobs=j;clock=c;}
 @Scheduled(fixedDelayString="${app.reports.schedule-poll-millis:60000}") @Transactional public void enqueueDue(){Instant now=clock.instant();for(ReportSchedule s:schedules.findByActiveTrueAndNextRunAtLessThanEqual(now)){var user=users.findById(s.getOwnerId()).orElse(null);if(user==null||!user.isActive()||!RolePermissions.has(user.getRole(),Permission.REPORT_MANAGE)){s.setActive(false);continue;}ReportRequest r=new ReportRequest();r.setOwnerId(s.getOwnerId());r.setDefinitionKey(s.getDefinitionKey());r.setFormat(s.getFormat());r.setStatus(ReportStatus.QUEUED);r.setFiltersJson(s.getFiltersJson());r.setPermissionSnapshot(String.join(",",RolePermissions.forRole(user.getRole()).stream().map(Enum::name).sorted().toList()));r.setTimezone(s.getTimezone());r.setLocale("sr-RS");r.setSnapshotAt(now);r.setProgress(0);requests.saveAndFlush(r);r.setJobId(jobs.enqueue(ReportService.JOB_TYPE,Map.of("reportId",r.getId()),"scheduled-report:"+s.getId()+":"+s.getNextRunAt()));s.setLastRunAt(now);s.setNextRunAt(ReportService.next(s.getTimezone(),s.getLocalTime(),s.getDayOfWeek(),now));}}
}
